 const byName=new Map(),byId=new Map(),events=new Map(),venues=new Map(global.venues.map(v=>[v.id,v])),profiles=new Map(global.artists.filter(a=>!a.isCandidate).map(a=>[a.id,a]));
 const add=(map,key,e)=>{if(!key)return;let ids=map.get(key);if(!ids)map.set(key,ids=new Set());ids.add(e.id)};
 let credits=0;
 for(const e of global.events){events.set(e.id,e);for(const name of new Set(e.artists||[])){add(byName,norm(name),e);credits++}for(const id of new Set(e.artistIds||[]))if(profiles.has(id)&&!profiles.get(id).isCredit)add(byId,id,e)}
 // Explicit IDs represent catalog links; name-only matches are possible identities, not merged profiles.
